				.enabled(true)
				.menuPath("Help", runtimeInfoActionName)
				.menuGroup(ToolConstants.HELP_RUNTIME_MENU_GROUP)
				.helpLocation(getRuntimeInfoHelpLocation())
				.buildAndInstall(tool);
	}

	/* @Override */
